// what lit the pip: the items new since the last visit glow for this visit (player.state.slateFresh, set when the app opens)
function freshCss(player,tab,plan,loom){const F=player?.state?.slateFresh,APP={board:'board',miles:'board',cam:'board',diary:'diary',crowd:'crowd',gallery:'gallery'},app=APP[tab];if(!app)return '';
 const seenL=player?.state?.slateSeen?.[app],live=seenL?(()=>{const S=new Set(seenL);return idsOf(app,plan||{},loom).filter(i=>!S.has(i));})():[];
 const all=[...new Set([...(F&&F.app===app?F.ids||[]:[]),...live])];if(!all.length)return '';const ids=[...new Set(all.map(i=>String(i).split('~')[0].replace(/[^\w-]/g,'')))].filter(Boolean);if(!ids.length)return '';
 const sel=ids.flatMap(i=>[`[data-id="${i}"]`,`[onclick*="id:'${i}'"]:not(button)`]).join(',');
 return `<style>@keyframes slFresh{0%,100%{box-shadow:0 0 0 2px #ff9156,0 0 14px #ff915688}50%{box-shadow:0 0 0 2px #ffd79a,0 0 22px #ff9156cc}}${sel}{animation:slFresh 1.6s ease-in-out 4;box-shadow:0 0 0 2px #ff9156;border-radius:4px;position:relative}</style><div style="display:flex;align-items:center;gap:8px;margin:0 0 10px;padding:6px 10px;border:1px solid #ff915666;background:#ff91561a;border-radius:4px;font-size:11px;color:#ffd0b0"><span style="background:#ff9156;color:#111b2c;border-radius:10px;padding:1px 7px;font-weight:700">${ids.length}</span> new since you last looked, glowing below</div>`;}
